INSERT OR IGNORE INTO self_check_tests
(id, slug, version, title, description, subject, topic, level, estimated_minutes, status)
VALUES ('aritmeticka-posloupnost-ss-30-v1', 'aritmeticka-posloupnost-ss-30', 1, 'Aritmetická posloupnost — self-check (30 úloh)',
'30 úloh / 60 bodů / přibližně 35–45 minut. Diference, obecný člen, dva známé členy, součty, aritmetický průměr a kombinované slovní úlohy. Verze pro studentský portál: výběr z možností, serverové vyhodnocení a podrobné vysvětlení.',
'Matematika', 'Aritmetická posloupnost', 'SŠ / maturita', 40, 'published');

INSERT OR IGNORE INTO self_check_questions
(id, test_id, position, prompt, options_json, correct_answer, explanation, points)
VALUES
('aritmeticka-posloupnost-ss-30-v1-q01', 'aritmeticka-posloupnost-ss-30-v1', 1, '{"instruction":"V posloupnosti 4, 9, 14, 19, … urči diferenci d.","category":"Základy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:6]]"},{"id":"b","label":"[[math:5]]"},{"id":"c","label":"[[math:4]]"},{"id":"d","label":"[[math:8]]"}]', 'b', 'Rozdíl sousedních členů: d = 9 − 4 = 5.', 2),
('aritmeticka-posloupnost-ss-30-v1-q02', 'aritmeticka-posloupnost-ss-30-v1', 2, '{"instruction":"Je dáno a₁ = 8, d = 3. Urči a₆.","category":"Základy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:23]]"},{"id":"b","label":"[[math:25]]"},{"id":"c","label":"[[math:21]]"},{"id":"d","label":"[[math:27]]"}]', 'a', 'a₆ = 8 + (6−1)·3 = 23.', 2),
('aritmeticka-posloupnost-ss-30-v1-q03', 'aritmeticka-posloupnost-ss-30-v1', 3, '{"instruction":"Je dáno a₁ = 14, d = −2. Urči a₉.","category":"Základy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:1]]"},{"id":"b","label":"[[math:-5]]"},{"id":"c","label":"[[math:3]]"},{"id":"d","label":"[[math:-2]]"}]', 'd', 'a₉ = 14 + 8·(−2) = −2.', 2),
('aritmeticka-posloupnost-ss-30-v1-q04', 'aritmeticka-posloupnost-ss-30-v1', 4, '{"instruction":"V posloupnosti −3, 1, 5, 9, … urči a₁₀.","category":"Základy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:37]]"},{"id":"b","label":"[[math:29]]"},{"id":"c","label":"[[math:33]]"},{"id":"d","label":"[[math:39]]"}]', 'c', 'd = 4, takže a₁₀ = −3 + 9·4 = 33.', 2),
('aritmeticka-posloupnost-ss-30-v1-q05', 'aritmeticka-posloupnost-ss-30-v1', 5, '{"instruction":"Je dáno a₇ = 25, d = 4. Urči a₁.","category":"Základy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:2]]"},{"id":"b","label":"[[math:1]]"},{"id":"c","label":"[[math:0]]"},{"id":"d","label":"[[math:4]]"}]', 'b', 'a₇ = a₁ + 6·4 ⇒ a₁ = 25 − 24 = 1.', 2),
('aritmeticka-posloupnost-ss-30-v1-q06', 'aritmeticka-posloupnost-ss-30-v1', 6, '{"instruction":"V posloupnosti 31, 26, 21, 16, … urči d.","category":"Základy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:-5]]"},{"id":"b","label":"[[math:-3]]"},{"id":"c","label":"[[math:-7]]"},{"id":"d","label":"[[math:-1]]"}]', 'a', 'd = 26 − 31 = −5.', 2),
('aritmeticka-posloupnost-ss-30-v1-q07', 'aritmeticka-posloupnost-ss-30-v1', 7, '{"instruction":"Je dáno a₄ = 11 a a₁₀ = 35. Urči d.","category":"Dva známé členy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:7]]"},{"id":"b","label":"[[math:1]]"},{"id":"c","label":"[[math:9]]"},{"id":"d","label":"[[math:4]]"}]', 'd', 'd = (35 − 11)/(10 − 4) = 24/6 = 4.', 2),
('aritmeticka-posloupnost-ss-30-v1-q08', 'aritmeticka-posloupnost-ss-30-v1', 8, '{"instruction":"Je dáno a₄ = 11 a a₁₀ = 35. Urči a₁.","category":"Dva známé členy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:3]]"},{"id":"b","label":"[[math:-5]]"},{"id":"c","label":"[[math:-1]]"},{"id":"d","label":"[[math:5]]"}]', 'c', 'Z předchozího d = 4. a₁ = 11 − 3·4 = −1.', 2),
('aritmeticka-posloupnost-ss-30-v1-q09', 'aritmeticka-posloupnost-ss-30-v1', 9, '{"instruction":"Je dáno a₃ = 16 a a₈ = 1. Urči d.","category":"Dva známé členy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:-2]]"},{"id":"b","label":"[[math:-3]]"},{"id":"c","label":"[[math:-4]]"},{"id":"d","label":"[[math:0]]"}]', 'b', 'd = (1 − 16)/(8 − 3) = −15/5 = −3.', 2),
('aritmeticka-posloupnost-ss-30-v1-q10', 'aritmeticka-posloupnost-ss-30-v1', 10, '{"instruction":"Je dáno a₅ = −3 a a₁₂ = 25. Urči d.","category":"Dva známé členy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:4]]"},{"id":"b","label":"[[math:6]]"},{"id":"c","label":"[[math:2]]"},{"id":"d","label":"[[math:8]]"}]', 'a', 'd = (25 − (−3))/(12 − 5) = 28/7 = 4.', 2),
('aritmeticka-posloupnost-ss-30-v1-q11', 'aritmeticka-posloupnost-ss-30-v1', 11, '{"instruction":"Je dáno a₆ = 9 a a₁₄ = 41. Urči a₂₀.","category":"Dva známé členy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:68]]"},{"id":"b","label":"[[math:62]]"},{"id":"c","label":"[[math:70]]"},{"id":"d","label":"[[math:65]]"}]', 'd', 'd = (41 − 9)/8 = 4; a₂₀ = 41 + 6·4 = 65.', 2),
('aritmeticka-posloupnost-ss-30-v1-q12', 'aritmeticka-posloupnost-ss-30-v1', 12, '{"instruction":"Je dáno a₁₁ = 40 a a₂₁ = 10. Urči a₁.","category":"Dva známé členy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:74]]"},{"id":"b","label":"[[math:66]]"},{"id":"c","label":"[[math:70]]"},{"id":"d","label":"[[math:76]]"}]', 'c', 'd = (10 − 40)/10 = −3; a₁ = 40 − 10·(−3) = 70.', 2),
('aritmeticka-posloupnost-ss-30-v1-q13', 'aritmeticka-posloupnost-ss-30-v1', 13, '{"instruction":"Vypočti S₁₀, je-li a₁ = 2 a d = 3.","category":"Součty","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:156]]"},{"id":"b","label":"[[math:155]]"},{"id":"c","label":"[[math:154]]"},{"id":"d","label":"[[math:158]]"}]', 'b', 'a₁₀ = 29; S₁₀ = 10·(2 + 29)/2 = 155.', 2),
('aritmeticka-posloupnost-ss-30-v1-q14', 'aritmeticka-posloupnost-ss-30-v1', 14, '{"instruction":"Vypočti S₂₀ posloupnosti 5, 9, 13, 17, …","category":"Součty","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:860]]"},{"id":"b","label":"[[math:862]]"},{"id":"c","label":"[[math:858]]"},{"id":"d","label":"[[math:864]]"}]', 'a', 'a₂₀ = 5 + 19·4 = 81; S₂₀ = 20·(5 + 81)/2 = 860.', 2),
('aritmeticka-posloupnost-ss-30-v1-q15', 'aritmeticka-posloupnost-ss-30-v1', 15, '{"instruction":"Vypočti součet 1 + 2 + 3 + ··· + 100.","category":"Součty","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:5053]]"},{"id":"b","label":"[[math:5047]]"},{"id":"c","label":"[[math:5055]]"},{"id":"d","label":"[[math:5050]]"}]', 'd', 'S₁₀₀ = 100·(1 + 100)/2 = 5050.', 2),
('aritmeticka-posloupnost-ss-30-v1-q16', 'aritmeticka-posloupnost-ss-30-v1', 16, '{"instruction":"Vypočti S₈, je-li a₁ = 10 a d = −2.","category":"Součty","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:28]]"},{"id":"b","label":"[[math:20]]"},{"id":"c","label":"[[math:24]]"},{"id":"d","label":"[[math:30]]"}]', 'c', 'a₈ = 10 − 14 = −4; S₈ = 8·(10 − 4)/2 = 24.', 2),
('aritmeticka-posloupnost-ss-30-v1-q17', 'aritmeticka-posloupnost-ss-30-v1', 17, '{"instruction":"Kolik členů obsahuje 7, 12, 17, …, 102?","category":"Součty","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:21]]"},{"id":"b","label":"[[math:20]]"},{"id":"c","label":"[[math:19]]"},{"id":"d","label":"[[math:23]]"}]', 'b', '102 = 7 + (n−1)·5 ⇒ n − 1 = 19 ⇒ n = 20.', 2),
('aritmeticka-posloupnost-ss-30-v1-q18', 'aritmeticka-posloupnost-ss-30-v1', 18, '{"instruction":"Je dáno a₁ = 3 a a₂₁ = 63. Vypočti S₂₁.","category":"Součty","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:693]]"},{"id":"b","label":"[[math:695]]"},{"id":"c","label":"[[math:691]]"},{"id":"d","label":"[[math:697]]"}]', 'a', 'S₂₁ = 21·(3 + 63)/2 = 693.', 2),
('aritmeticka-posloupnost-ss-30-v1-q19', 'aritmeticka-posloupnost-ss-30-v1', 19, '{"instruction":"Doplň prostřední člen aritmetické posloupnosti: 14, ?, 38.","category":"Vlastnosti a slovní úlohy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:29]]"},{"id":"b","label":"[[math:23]]"},{"id":"c","label":"[[math:31]]"},{"id":"d","label":"[[math:26]]"}]', 'd', 'Prostřední člen je průměr: (14 + 38)/2 = 26.', 2),
('aritmeticka-posloupnost-ss-30-v1-q20', 'aritmeticka-posloupnost-ss-30-v1', 20, '{"instruction":"Součet tří po sobě jdoucích členů je 45. Urči prostřední člen.","category":"Vlastnosti a slovní úlohy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:19]]"},{"id":"b","label":"[[math:11]]"},{"id":"c","label":"[[math:15]]"},{"id":"d","label":"[[math:21]]"}]', 'c', 'Piš x−d, x, x+d. Pak 3x = 45 ⇒ x = 15.', 2),
('aritmeticka-posloupnost-ss-30-v1-q21', 'aritmeticka-posloupnost-ss-30-v1', 21, '{"instruction":"Je dáno a₁₀ = 39 a d = 4. Urči a₁.","category":"Vlastnosti a slovní úlohy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:4]]"},{"id":"b","label":"[[math:3]]"},{"id":"c","label":"[[math:2]]"},{"id":"d","label":"[[math:6]]"}]', 'b', 'a₁ = 39 − 9·4 = 3.', 2),
('aritmeticka-posloupnost-ss-30-v1-q22', 'aritmeticka-posloupnost-ss-30-v1', 22, '{"instruction":"První týden uspoříš 100 Kč a každý další o 20 Kč více. Kolik Kč uspoříš ve 12. týdnu?","category":"Vlastnosti a slovní úlohy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:320]]"},{"id":"b","label":"[[math:322]]"},{"id":"c","label":"[[math:318]]"},{"id":"d","label":"[[math:324]]"}]', 'a', 'a₁₂ = 100 + 11·20 = 320 Kč.', 2),
('aritmeticka-posloupnost-ss-30-v1-q23', 'aritmeticka-posloupnost-ss-30-v1', 23, '{"instruction":"Při stejném týdenním spoření (100 Kč, každý další týden o 20 Kč více) kolik Kč uspoříš za 10 týdnů celkem?","category":"Vlastnosti a slovní úlohy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:1903]]"},{"id":"b","label":"[[math:1897]]"},{"id":"c","label":"[[math:1905]]"},{"id":"d","label":"[[math:1900]]"}]', 'd', 'a₁₀ = 280; S₁₀ = 10·(100 + 280)/2 = 1900 Kč.', 2),
('aritmeticka-posloupnost-ss-30-v1-q24', 'aritmeticka-posloupnost-ss-30-v1', 24, '{"instruction":"V první řadě je 12 sedadel, v každé další o 3 více. Kolik sedadel má 15. řada?","category":"Vlastnosti a slovní úlohy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:58]]"},{"id":"b","label":"[[math:50]]"},{"id":"c","label":"[[math:54]]"},{"id":"d","label":"[[math:60]]"}]', 'c', 'a₁₅ = 12 + 14·3 = 54 sedadel.', 2),
('aritmeticka-posloupnost-ss-30-v1-q25', 'aritmeticka-posloupnost-ss-30-v1', 25, '{"instruction":"Doplň prostřední člen: 6, ?, 20.","category":"Kombinované úlohy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:14]]"},{"id":"b","label":"[[math:13]]"},{"id":"c","label":"[[math:12]]"},{"id":"d","label":"[[math:16]]"}]', 'b', 'x = (6 + 20)/2 = 13.', 2),
('aritmeticka-posloupnost-ss-30-v1-q26', 'aritmeticka-posloupnost-ss-30-v1', 26, '{"instruction":"Je dáno a₁ = 5, d = 3 a Sₙ = 670. Urči n.","category":"Kombinované úlohy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:20]]"},{"id":"b","label":"[[math:22]]"},{"id":"c","label":"[[math:18]]"},{"id":"d","label":"[[math:24]]"}]', 'a', '670 = n[10+3(n−1)]/2 ⇒ 3n²+7n−1340=0 ⇒ n=20.', 2),
('aritmeticka-posloupnost-ss-30-v1-q27', 'aritmeticka-posloupnost-ss-30-v1', 27, '{"instruction":"Je dáno a₁ = 4, d = 2 a Sₙ = 180. Urči n.","category":"Kombinované úlohy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:15]]"},{"id":"b","label":"[[math:9]]"},{"id":"c","label":"[[math:17]]"},{"id":"d","label":"[[math:12]]"}]', 'd', 'Sₙ = n(4 + (n−1)) = n(n+3); n(n+3)=180 ⇒ n=12.', 2),
('aritmeticka-posloupnost-ss-30-v1-q28', 'aritmeticka-posloupnost-ss-30-v1', 28, '{"instruction":"Je dáno a₁ = 7, d = −2. Jaký index má první záporný člen?","category":"Kombinované úlohy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:9]]"},{"id":"b","label":"[[math:1]]"},{"id":"c","label":"[[math:5]]"},{"id":"d","label":"[[math:11]]"}]', 'c', 'aₙ = 7 − 2(n−1) = 9−2n < 0, tedy první n = 5.', 2),
('aritmeticka-posloupnost-ss-30-v1-q29', 'aritmeticka-posloupnost-ss-30-v1', 29, '{"instruction":"Je dáno a₅ = 18 a a₁₂ = 46. Urči a₂₀.","category":"Kombinované úlohy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:79]]"},{"id":"b","label":"[[math:78]]"},{"id":"c","label":"[[math:77]]"},{"id":"d","label":"[[math:81]]"}]', 'b', 'd = (46−18)/7 = 4; a₁ = 2; a₂₀ = 2 + 19·4 = 78.', 2),
('aritmeticka-posloupnost-ss-30-v1-q30', 'aritmeticka-posloupnost-ss-30-v1', 30, '{"instruction":"Vypočti S₇, je-li a₁ = 12 a d = −3.","category":"Kombinované úlohy","hint":"Použij vztah pro n-tý člen nebo součet aritmetické posloupnosti."}', '[{"id":"a","label":"[[math:21]]"},{"id":"b","label":"[[math:23]]"},{"id":"c","label":"[[math:19]]"},{"id":"d","label":"[[math:25]]"}]', 'a', 'a₇ = 12−6·3 = −6; S₇ = 7·(12−6)/2 = 21.', 2);
